/* Diagnostic reasoning normalization. Existing flows are preserved, while each
   node receives an explicit TEST/WHY/EXPECTED/IF NORMAL/IF ABNORMAL/NEXT STEP
   contract. Numeric or model-specific statements are audit metadata only and
   are not promoted to verified universal facts. */
var DIAGNOSTIC_AUDIT_RECORDS = [];
DIAG_FLOWS.forEach(flow => {
  Object.entries(flow.nodes).forEach(([nodeId, node]) => {
    if (node.q) {
      node.test = node.q;
      node.why = node.why || flow.first || { fa: 'این مشاهده شاخه بعدی و آزمون کم‌خطرتر را تعیین می‌کند.', en: 'This observation selects the next, lower-risk test.' };
      node.expectedResult = node.expect || { fa: 'نتیجه باید با پلاک، نقشه یا منوال همان دستگاه مقایسه شود.', en: 'Compare with the nameplate, wiring diagram or manual for this device.' };
      node.ifNormal = node.opts && node.opts[0] ? node.opts[0].l : null;
      node.ifAbnormal = node.opts && node.opts[1] ? node.opts[1].l : null;
      node.nextStep = { fa: 'فقط شاخه منطبق با شواهد ثبت‌شده را ادامه دهید؛ علت حذف‌شده را تکرار نکنید.', en: 'Continue only the branch supported by recorded evidence; do not repeat eliminated causes.' };
    } else {
      node.rootCause = node.title;
      node.repair = node.actions || [];
      node.verification = node.next || { fa: 'پس از بازیابی کامل، آزمون عملکردی را طبق روش همان دستگاه ثبت کنید.', en: 'After full restoration, record a functional test using the device procedure.' };
    }
    /* Classify on the fa source text only, so translations never reclassify a node. */
    var stripEn = v => Array.isArray(v) ? v.map(stripEn) : (v && typeof v === 'object'
      ? Object.fromEntries(Object.entries(v).filter(([k]) => k !== 'en').map(([k, x]) => [k, stripEn(x)])) : v);
    const text = JSON.stringify(stripEn(node));
    const status = /مدل|منوال|پارامتر|firmware|terminal|درایو|برد/i.test(text)
      ? 'MODEL-DEPENDENT'
      : /\d|EN\s*81|6303|استاندارد/i.test(text)
        ? 'UNVERIFIED'
        : 'ENGINEERING PRACTICE';
    node.verificationStatus = status;
    DIAGNOSTIC_AUDIT_RECORDS.push({
      id: flow.id + ':' + nodeId, symptom: flow.symptom, nodeId,
      test: node.test || null, why: node.why || null, expectedResult: node.expectedResult || null,
      ifNormal: node.ifNormal || null, ifAbnormal: node.ifAbnormal || null,
      nextStep: node.nextStep || node.next || null, verificationStatus: status, source: null
    });
  });
});
